# Cloud Monitoring alerts for OpenFang Hand → Vertex AI inference (TI-1425)
#
# Alerts:
#   1. Vertex AI quota usage >80% por 1h → email DevOps
#   2. Vertex AI 5xx error rate >1% por 5min → email DevOps
#   3. Project budget alert $280/mes → email DevOps + finops
#
# Notification channel: reusa el SA-managed email channel del módulo ai-vm
# (creado por tf-modules//vm con alert_email = "dev@liftit.co").

# ----------------------------------------------------------------------------
# Notification channel — referencia al existente del orchestrator VM
# ----------------------------------------------------------------------------

# El módulo ai-vm["ai-infra-orchestrator"] crea un notification channel para
# sus propias alertas de VM down. Lo reusamos para Vertex AI alerts via lookup.
data "google_monitoring_notification_channel" "openfang_email" {
  display_name = "Email Alert"
  type         = "email"
  project      = local.project_id[terraform.workspace]
  labels = {
    email_address = "dev@liftit.co"
  }
}

# ----------------------------------------------------------------------------
# Alert 1 — Vertex AI quota usage >80% sostenido por 1h
# ----------------------------------------------------------------------------
# Quota de Gemini 2.5 Flash regional us-east1 default = 60 RPM por proyecto.
# Si se acerca al límite, indica necesidad de quota increase request.

resource "google_monitoring_alert_policy" "vertex_ai_quota_exhaustion" {
  display_name = "OpenFang — Vertex AI quota >80% por 1h"
  project      = local.project_id[terraform.workspace]
  combiner     = "OR"

  conditions {
    display_name = "Quota usage ratio >80%"

    condition_threshold {
      filter = "metric.type=\"serviceruntime.googleapis.com/quota/rate/net_usage\" resource.type=\"consumer_quota\" resource.label.\"service\"=\"aiplatform.googleapis.com\""
      duration        = "3600s" # 1h
      comparison      = "COMPARISON_GT"
      threshold_value = 0.8

      aggregations {
        alignment_period   = "300s"
        per_series_aligner = "ALIGN_RATE"
      }
    }
  }

  notification_channels = [data.google_monitoring_notification_channel.openfang_email.name]

  documentation {
    content   = <<-EOT
      OpenFang Hand está consumiendo >80% del quota de Vertex AI Gemini Flash (us-east1).

      **Acciones:**
      1. Verificar si hay un loop o tool-storm en OpenFang: revisar logs orchestrator VM
      2. Si tráfico legítimo: solicitar quota increase en https://console.cloud.google.com/iam-admin/quotas?project=prod-apps-454414
      3. Si abuse: pausar el bot vía Slack admin panel
    EOT
    mime_type = "text/markdown"
  }

  user_labels = merge(local.default_labels, {
    alert_type = "quota"
    component  = "vertex-ai"
  })
}

# ----------------------------------------------------------------------------
# Alert 2 — Vertex AI 5xx error rate >1% por 5min
# ----------------------------------------------------------------------------
# Captura errores transitorios del servicio managed o cuotas excedidas duras.

resource "google_monitoring_alert_policy" "vertex_ai_5xx_errors" {
  display_name = "OpenFang — Vertex AI 5xx error rate >1% por 5min"
  project      = local.project_id[terraform.workspace]
  combiner     = "OR"

  conditions {
    display_name = "5xx response codes from aiplatform.googleapis.com"

    condition_threshold {
      filter = "metric.type=\"serviceruntime.googleapis.com/api/request_count\" resource.type=\"consumed_api\" resource.label.\"service\"=\"aiplatform.googleapis.com\" metric.label.\"response_code_class\"=\"5xx\""
      duration        = "300s" # 5min
      comparison      = "COMPARISON_GT"
      threshold_value = 0.01 # 1% threshold (relative; precision de la métrica puede variar)

      aggregations {
        alignment_period   = "60s"
        per_series_aligner = "ALIGN_RATE"
      }
    }
  }

  notification_channels = [data.google_monitoring_notification_channel.openfang_email.name]

  documentation {
    content   = <<-EOT
      Vertex AI está devolviendo errores 5xx a OpenFang Hand.

      **Acciones:**
      1. Revisar status page: https://status.cloud.google.com/
      2. Logs LiteLLM en el VM: `ssh openfang "sudo docker logs openfang-litellm --tail 100"`
      3. Si Vertex AI está down: OpenFang seguirá fallando. Considerar fallback temporal a OpenRouter (ver runbook TI-1425 sec. Rollback)
    EOT
    mime_type = "text/markdown"
  }

  user_labels = merge(local.default_labels, {
    alert_type = "errors"
    component  = "vertex-ai"
  })
}

# ----------------------------------------------------------------------------
