resource "google_billing_budget" "openfang_monthly_budget" {
  billing_account = "018061-026989-F37DF2" # Liftit billing account
  display_name    = "OpenFang Hand monthly budget alert"

  budget_filter {
    projects = ["projects/${local.project_numbers[terraform.workspace]}"]

    # Solo gastos atribuidos a Vertex AI + Compute Engine de la VM orchestrator
    services = [
      "services/CCD8-9BF1-090E", # Vertex AI
      "services/6F81-5844-456A", # Compute Engine (orchestrator VM)
    ]

    labels = {
      service = ["ai-infra-orchestrator"]
    }
  }

  amount {
    specified_amount {
      currency_code = "USD"
      units         = "280"
    }
